boolean add(String element) {
    long h = hash64(element);
    int index = (int) (h & ((1 << p) - 1));              // low p bits pick the register
    long rest = (h >>> p) | (1L << (64 - p));           // the other bits, with a stop bit on top
    int rank = Long.numberOfTrailingZeros(rest) + 1;    // zeros before the first 1, plus one
    if (rank <= registers[index]) return false;         // a run this long was seen already
    registers[index] = (byte) rank;
    return true;
}
